//! 🎯️ An actual intent retains its original argument slots and selected metadata through every pending command turn.
use super::*;
use semio_framework_job::{OriginalConstructionAdmission,StepContext,OriginalSourceBinding,OriginalTurnFailure};
use semio_framework_value::{RetirementDemand,RetainedCloneStep,ValueError,ValueRefusalKind,retained_clone::RetainedCloneClose};
use semio_framework_value::retained_clone::NativeAllocationIdentity;
use semio_plugin_job_receiving::original_steps::{construction,receipt};
use std::mem::{ManuallyDrop,size_of};
use crate::{adopted,begun,built,built_with,retired,retired_poll,unbuilt};
/// 🧷️ The receiving batch keeps the same actual intent cell until both original UI roots and selected surface are restored.
pub struct OriginalIntentActionSource{binding:OriginalSourceBinding,decoder:(NativeAllocationIdentity,u64),intent:usize,body:usize,instance:u32,conversion:ManuallyDrop<Option<Box<ui_contract::OriginalUiArguments>>>,context:ManuallyDrop<Option<Box<OriginalResponseActionSource>>>,pub arguments:ManuallyDrop<Option<DslValue>>,pub failure:ManuallyDrop<Option<Fault>>,arguments_ready:bool,retirement:RetainedCloneClose,construction:OriginalConstructionAdmission}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original intent changed its actual receiving cell or command continuation")}
impl OriginalIntentActionSource{
 pub fn birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>(),capacity_bytes:size_of::<Self>(),depth:1,..Default::default()}}
 pub fn admit(instance:u32,intent:&ui_contract::UiIntent,cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let binding=OriginalSourceBinding::borrow(cx);let intent=intent as*const _ as usize;let body=cx.retained_grant().maximum_copy_bytes;let d=Self::birth_demands();let settled=built_with(cx,admission,output,construction(d),|native|{let decoder=(native.ledger_identity(),native.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::write(Box::new_uninit(),Self{binding,decoder,intent,body,instance,conversion:ManuallyDrop::new(None),context:ManuallyDrop::new(None),arguments:ManuallyDrop::new(None),failure:ManuallyDrop::new(None),arguments_ready:false,retirement:Default::default(),construction:Default::default()}),receipt(d)))})?;Ok(adopted(settled,admission,output,|owner|&mut owner.construction))}
 fn validate(&self,intent:&ui_contract::UiIntent,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if self.intent!=intent as*const _ as usize||!self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 pub fn ready(&self)->bool{self.arguments_ready&&self.context.as_ref().is_some_and(|context|context.ready())}
 pub fn command_inputs(&mut self)->Result<(&mut Option<DslValue>,&mut Option<Fault>,&mut Option<ActionMeta>),ValueError>{if !self.ready(){return Err(invalid())}Ok((&mut self.arguments,&mut self.failure,&mut self.context.as_mut().ok_or_else(invalid)?.metadata))}
 pub fn metadata_mut(&mut self)->Result<&mut Option<ActionMeta>,ValueError>{if !self.ready(){return Err(invalid())}Ok(&mut self.context.as_mut().ok_or_else(invalid)?.metadata)}
 pub async fn advance<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,intent:&mut ui_contract::UiIntent,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(intent,cx)?;if !self.arguments_ready{if self.conversion.is_none(){ui_contract::OriginalUiArguments::admit(&mut intent.args,&mut intent.input,cx,&mut self.conversion)?;return Ok(false)}let conversion=self.conversion.as_mut().unwrap();if conversion.ready(){conversion.take_into(&mut self.arguments,cx)?;}else if conversion.output_taken(){if conversion.terminal_is_empty(){let mut d=ui_contract::OriginalUiArguments::release_demands();d.copy_bytes=size_of::<bool>();let mut done=None;built(cx,&mut self.construction,&mut done,construction(d),||{self.conversion.take();self.arguments_ready=true;Ok(((),receipt(d)))})?;}else{conversion.close_step(&mut intent.args,&mut intent.input,cx)?;}}else{conversion.advance(&mut intent.args,&mut intent.input,cx)?;}return Ok(false)}if self.context.is_none(){OriginalResponseActionSource::admit_surface(self.instance,intent.surface.as_ref(),cx,&mut self.construction,&mut self.context)?;return Ok(false)}self.context.as_mut().unwrap().advance_surface(runtime,intent.surface.as_ref(),cx).await}
 pub fn close_demands(&self,registry:&semio_plugin_plugin_program::surface_context::SurfaceContexts)->Result<RetirementDemand,ValueError>{if let Some(conversion)=self.conversion.as_ref(){return if conversion.terminal_is_empty(){Ok(ui_contract::OriginalUiArguments::release_demands())}else{conversion.close_demands()}}if let Some(context)=self.context.as_ref(){return if context.terminal_is_empty(){Ok(OriginalResponseActionSource::release_demand())}else{context.close_demands(registry)}}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.arguments.is_some(){return self.retirement.next_owner_demands::<DslValue>(true,&None,self.body)}if self.failure.is_some(){return self.retirement.next_owner_demands::<Fault>(true,&None,self.body)}Ok(Default::default())}
 pub async fn close_step<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,intent:&mut ui_contract::UiIntent,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(intent,cx)?;if let Some(conversion)=self.conversion.as_mut(){if conversion.terminal_is_empty(){let d=ui_contract::OriginalUiArguments::release_demands();retired(cx,d,|_|{self.conversion.take();Ok(RetainedCloneStep::Progress(receipt(d)))})?;}else{conversion.close_step(&mut intent.args,&mut intent.input,cx)?;}return Ok(false)}if let Some(context)=self.context.as_mut(){if context.terminal_is_empty(){let d=OriginalResponseActionSource::release_demand();retired(cx,d,|_|{self.context.take();Ok(RetainedCloneStep::Progress(receipt(d)))})?;}else{context.close_step(runtime,cx).await?;}return Ok(false)}if !self.retirement.is_empty(){let d=self.retirement.demands(self.body)?;retired_poll(cx,d,|effect|self.retirement.step_granted(self.body,effect))?;return Ok(false)}if self.arguments.is_some(){let d=self.retirement.next_owner_demands::<DslValue>(true,&None,self.body)?;begun(cx,d,|effect|self.retirement.begin_granted(&mut self.arguments,effect))?;return Ok(false)}if self.failure.is_some(){let d=self.retirement.next_owner_demands::<Fault>(true,&None,self.body)?;begun(cx,d,|effect|self.retirement.begin_granted(&mut self.failure,effect))?;return Ok(false)}unbuilt(cx,&mut self.construction)}
 pub fn terminal_is_empty(&self)->bool{self.conversion.is_none()&&self.context.is_none()&&self.arguments.is_none()&&self.failure.is_none()&&self.retirement.is_empty()&&self.construction.terminal_is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl Drop for OriginalIntentActionSource{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original intent source must restore its actual slots and surface before closing")}}
